import{c as o,Q as r,j as e,m as a}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"Anthropic pays $750,000+ a year for engineers to understand LLMs — full workshop","description":"","frontmatter":{"url":"https://x.com/vicky_grok/status/2070502864917877038","title":"Anthropic pays $750,000+ a year for engineers to understand LLMs — full workshop","author":"Vikas gupta","archived":"2026-06-27T00:00:00.000Z","duration":"01:29:02","handle":"@vicky_grok","published":"2026-06-26T00:00:00.000Z","subtitle_lang":"en","type":"video"},"headers":[],"relativePath":"research/tweets/2026-06-26-vicky_grok-2070502864917877038.md","filePath":"research/tweets/2026-06-26-vicky_grok-2070502864917877038.md","lastUpdated":1785909234000}'),n={name:"research/tweets/2026-06-26-vicky_grok-2070502864917877038.md"};function s(i,t,g,h,p,l){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="anthropic-pays-750-000-a-year-for-engineers-to-understand-llms-—-full-workshop-—-vicky-grok" tabindex="-1">Anthropic pays $750,000+ a year for engineers to understand LLMs — full workshop — @vicky_grok <a class="header-anchor" href="#anthropic-pays-750-000-a-year-for-engineers-to-understand-llms-—-full-workshop-—-vicky-grok" aria-label="Permalink to &quot;Anthropic pays $750,000+ a year for engineers to understand LLMs — full workshop — @vicky_grok&quot;">​</a></h1><p><strong>來源</strong>: <a href="https://x.com/vicky_grok/status/2070502864917877038" target="_blank" rel="noreferrer">https://x.com/vicky_grok/status/2070502864917877038</a><strong>作者</strong>: Vikas gupta (@vicky_grok) <strong>發布日期</strong>: 2026-06-26 <strong>收錄日期</strong>: 2026-06-27 <strong>時長</strong>: 01:29:02 <strong>語言</strong>: English</p><hr><h2 id="核心摘要" tabindex="-1">核心摘要 <a class="header-anchor" href="#核心摘要" aria-label="Permalink to &quot;核心摘要&quot;">​</a></h2><blockquote><p>這是一堂以「調查鏡頭」系統梳理現代 LLM Transformer 架構演進的完整工作坊課程，涵蓋從 Vaswani 原始論文到 LLaMA、Gemma、Qwen 等當代模型的架構選擇、超參數設定與訓練穩定性技巧。</p></blockquote><ul><li>現代大語言模型架構共識已高度收斂：Pre-Norm（RMSNorm）+ RoPE 位置編碼 + SwiGLU 門控激活函數幾乎是所有主流模型的標配</li><li>超參數設計有清晰的經驗法則：FFN 維度為模型維度的 4 倍、注意力頭數與頭維度相等、模型深度/寬度比值約維持在 100 左右</li><li>訓練穩定性關鍵介入手段包括：QK Norm（控制 softmax 輸入規模）與 Logit Soft Capping（Gemma 系列）</li><li>KV Cache 機制帶來推理效率問題，Group Query Attention（GQA）是目前最廣泛採用的平衡方案，在幾乎不損失表現力的前提下大幅降低記憶體存取成本</li><li>滑動視窗注意力（Sliding Window Attention）結合全局注意力的混合架構，是處理長上下文任務的主流趨勢</li></ul><hr><h2 id="整理版-可讀逐字稿" tabindex="-1">整理版（可讀逐字稿） <a class="header-anchor" href="#整理版-可讀逐字稿" aria-label="Permalink to &quot;整理版（可讀逐字稿）&quot;">​</a></h2><h3 id="課程導言-為何用調查視角看架構-00-00–04-50" tabindex="-1">課程導言：為何用調查視角看架構（00:00–04:50） <a class="header-anchor" href="#課程導言-為何用調查視角看架構-00-00–04-50" aria-label="Permalink to &quot;課程導言：為何用調查視角看架構（00:00–04:50）&quot;">​</a></h3><p>講師以「架構過去一直很難懂」開場，提出這堂課的核心策略：與其枚舉所有設計選擇，不如系統性地審視大量已發布的現代語言模型（Qwen2、Nemotron 4、Gemma 4、Marin 等），從中歸納哪些選擇是「固定的」、哪些是「可以變動的」。最好的學習方式是自己動手訓練模型，而第二好的方式就是從他人的大量實驗中汲取共識。</p><h3 id="transformer-基礎與架構變體-04-50–20-10" tabindex="-1">Transformer 基礎與架構變體（04:50–20:10） <a class="header-anchor" href="#transformer-基礎與架構變體-04-50–20-10" aria-label="Permalink to &quot;Transformer 基礎與架構變體（04:50–20:10）&quot;">​</a></h3><p>從 Vaswani et al. 的原始 Transformer 出發，說明其標準選擇：正弦/餘弦位置編碼、ReLU 激活函數、Post-Norm 層歸一化。現代模型（尤其是 LLaMA 系列帶頭）轉向三個關鍵改變：<strong>Pre-Norm</strong>（將 LayerNorm 移到殘差塊前）、<strong>RoPE</strong>（旋轉位置嵌入）、以及 <strong>SwiGLU</strong>（門控線性單元）。講師指出 RMSNorm 幾乎取代了標準 LayerNorm，因其去除偏置項可提升算術密度，同時表現力不變。</p><h3 id="門控線性單元-glu-swiglu-的原理-20-10–27-10" tabindex="-1">門控線性單元（GLU）：SwiGLU 的原理（20:10–27:10） <a class="header-anchor" href="#門控線性單元-glu-swiglu-的原理-20-10–27-10" aria-label="Permalink to &quot;門控線性單元（GLU）：SwiGLU 的原理（20:10–27:10）&quot;">​</a></h3><p>詳細拆解 ReLU FFN 到 GLU 的演進。標準 ReLU 網路：<code>x → W1 → ReLU → W2 → output</code>；GLU 額外引入一個「門控」分支 V，以逐元素乘法調變 ReLU 的輸出。SwiGLU 用 Swish 函數取代 ReLU，是目前最主流的變體。由於引入第三個矩陣 V，FFN 隱藏維度需縮小為原來的 2/3 以維持相同參數量。講師評論這幾乎是「免費的性能提升」。</p><h3 id="parallel-transformer-block-與架構實驗歷史-27-10–33-00" tabindex="-1">Parallel Transformer Block 與架構實驗歷史（27:10–33:00） <a class="header-anchor" href="#parallel-transformer-block-與架構實驗歷史-27-10–33-00" aria-label="Permalink to &quot;Parallel Transformer Block 與架構實驗歷史（27:10–33:00）&quot;">​</a></h3><p>介紹將注意力層與 MLP 層並行計算（而非串行）的架構變體，此想法源自 GPT-J，後被 PaLM 採用。並行化可共享層歸一化、融合矩陣乘法，帶來系統層面的優化空間。同期還介紹了多個 Google 在 2020 年代的架構實驗（Narang et al.），展現 Google 在架構上相較其他機構更願意大幅創新。</p><h3 id="rope-旋轉位置嵌入的數學原理-33-00–50-00" tabindex="-1">RoPE 旋轉位置嵌入的數學原理（33:00–50:00） <a class="header-anchor" href="#rope-旋轉位置嵌入的數學原理-33-00–50-00" aria-label="Permalink to &quot;RoPE 旋轉位置嵌入的數學原理（33:00–50:00）&quot;">​</a></h3><p>深入講解 RoPE 的核心思想：位置嵌入應只依賴相對位置差，而非絕對位置。傳統方法（絕對位置嵌入、相對位置嵌入加在注意力矩陣上）皆無法完美實現此特性。RoPE 的解法：對語義詞向量按位置旋轉，利用「旋轉不改變內積」的幾何性質確保相對不變性。高維實作方式是將 d 維向量切成 d/2 個二維塊，每對維度以不同頻率旋轉（類似傅立葉分解），高頻捕捉局部位置、低頻捕捉長程位置。</p><h3 id="超參數設計法則-50-00–01-05-00" tabindex="-1">超參數設計法則（50:00–01:05:00） <a class="header-anchor" href="#超參數設計法則-50-00–01-05-00" aria-label="Permalink to &quot;超參數設計法則（50:00–01:05:00）&quot;">​</a></h3><p>系統整理超參數設計的業界共識：FFN 維度 = 4 × 模型維度（「factor of 4」經驗法則）；注意力頭維度 = 模型維度 / 頭數，通常設為 64 或 128；模型的深度/寬度比（aspect ratio）約為 100。正則化方面，Dropout 在大規模預訓練中已基本廢棄（模型大、資料夠時自然正則化），但 weight decay 仍常用，且常與學習率聯動調整。</p><h3 id="訓練穩定性-qk-norm-與-logit-soft-capping-01-05-00–01-14-00" tabindex="-1">訓練穩定性：QK Norm 與 Logit Soft Capping（01:05:00–01:14:00） <a class="header-anchor" href="#訓練穩定性-qk-norm-與-logit-soft-capping-01-05-00–01-14-00" aria-label="Permalink to &quot;訓練穩定性：QK Norm 與 Logit Soft Capping（01:05:00–01:14:00）&quot;">​</a></h3><p>訓練穩定性的主要威脅來自 softmax 的指數運算與除法——兩者皆容易數值爆炸。<strong>QK Norm</strong> 的做法是在計算 attention 前對 Q 和 K 各自做 RMSNorm，控制 softmax 輸入規模。此技術起源於多模態模型（edifix、Chameleon），後被廣泛移植至語言模型；幾乎不影響模型表現，但有效防止注意力退化。<strong>Logit Soft Capping</strong>（Gemma 2/3/4）則更激進：用 tanh 對 logit 硬性截頂，是比 QK Norm 更強的干預，但可能有輕微的表現損失。</p><h3 id="group-query-attention-gqa-與推理效率-01-14-00–01-29-02" tabindex="-1">Group Query Attention（GQA）與推理效率（01:14:00–01:29:02） <a class="header-anchor" href="#group-query-attention-gqa-與推理效率-01-14-00–01-29-02" aria-label="Permalink to &quot;Group Query Attention（GQA）與推理效率（01:14:00–01:29:02）&quot;">​</a></h3><p>解釋 KV Cache 機制為何在推理時造成記憶體頻寬瓶頸：每一步 decode 都要讀入完整的 KV 參數，導致算術密度下降。<strong>MQA</strong>（Multi-Query Attention）將所有頭共享同一組 K、V，大幅減少記憶體存取，但損失表現力。<strong>GQA</strong>（Group Query Attention）折中：K/V 頭數少於 Q 頭數，形成「每組 Q 頭共用一組 KV」的結構，在幾乎不損性能的前提下獲得顯著推理加速。今日幾乎所有主流模型都採用 GQA。最後介紹<strong>滑動視窗注意力</strong>（Sliding Window Attention，GPT-3 即有此概念），以及近期混合全局+局部注意力架構處理長上下文的趨勢，課程到此作結。</p><hr><h2 id="逐字稿-含時間戳" tabindex="-1">逐字稿（含時間戳） <a class="header-anchor" href="#逐字稿-含時間戳" aria-label="Permalink to &quot;逐字稿（含時間戳）&quot;">​</a></h2><p><strong>[00:00 → 00:03]</strong> So today, we&#39;re going to talk about architecture, which at least to me has</p><p><strong>[00:03 → 00:06]</strong> always been pretty insiinscrutable.</p><p><strong>[00:06 → 00:10]</strong> And so I&#39;m going to take the approach of just telling you kind of everything, right?</p><p><strong>[00:10 → 00:13]</strong> I&#39;m going to go through all of the modern papers and</p><p><strong>[00:13 → 00:16]</strong> we&#39;re going to just look through what has everyone done.</p><p><strong>[00:16 → 00:22]</strong> And so I&#39;ve titled this</p><p><strong>[00:30 → 00:31]</strong> where we are.</p><p><strong>[00:31 → 00:36]</strong> So okay, what we are going to do is we are going to try to understand architecture</p><p><strong>[00:36 → 00:39]</strong> from kind of like a survey lens, right?</p><p><strong>[00:39 → 00:42]</strong> The best thing to do, better than listening to the lecture even,</p><p><strong>[00:42 → 00:46]</strong> is for you to go out and train your own models and try different architectures,</p><p><strong>[00:46 → 00:49]</strong> by far the best thing to do, that&#39;s part of the philosophy of the course.</p><p><strong>[00:49 → 00:53]</strong> But, we&#39;re not going to be able to cover the whole design space of all the</p><p><strong>[00:53 → 00:55]</strong> different architectures that are out there, right?</p><p><strong>[00:55 → 00:57]</strong> , like that&#39;s not something that we have to compute or</p><p><strong>[00:57 → 00:58]</strong> the time to do.</p><p><strong>[00:58 → 01:02]</strong> So my opinion is the second best thing that we could do,</p><p><strong>[01:02 → 01:04]</strong> is to try to learn from the experience of others, right?</p><p><strong>[01:04 → 01:06]</strong> What has everyone else done?</p><p><strong>[01:06 → 01:08]</strong> What are the choices that they are making, right?</p><p><strong>[01:08 → 01:11]</strong> And by looking at kind of a broader somewhat zoomed out picture,</p><p><strong>[01:11 → 01:15]</strong> maybe we can start to understand, these are the kinds of parameters and</p><p><strong>[01:15 → 01:18]</strong> choices that are sort of fixed across all effective architectures.</p><p><strong>[01:18 → 01:21]</strong> And these other ones can be the sort of</p><p><strong>[01:21 → 01:23]</strong> varied without impacting how the model perform, right?</p><p><strong>[01:24 → 01:26]</strong> So I&#39;m going to talk about basically transformer variants.</p><p><strong>[01:26 → 01:31]</strong> Like what is the modern transformer starting with the Vaswani paper?</p><p><strong>[01:31 → 01:36]</strong> And then as we go to more modern, more recent architectures,</p><p><strong>[01:36 → 01:37]</strong> what do they have in common?</p><p><strong>[01:37 → 01:39]</strong> And then what are we allowed to vary, or not allowed, but</p><p><strong>[01:39 → 01:43]</strong> what do people vary as they go through this, right?</p><p><strong>[01:43 → 01:47]</strong> So I think many of you have taken an NLP course of some kind,</p><p><strong>[01:47 → 01:48]</strong> or at least seen a transformer.</p><p><strong>[01:48 → 01:49]</strong> So you&#39;ve probably seen the very vanilla</p><p><strong>[01:49 → 01:54]</strong> transformer from Vaswani at all.</p><p>[... 共 2398 行，完整逐字稿見 /tmp/claude-scratch/out/vicky_grok.txt ...]</p>',62)])])}const u=o(n,[["render",s]]);export{c as __pageData,u as default};
